testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { faltantesNoAmbiente, versaoDoRollback } from './solution.mjs';

test('faltantesNoAmbiente acha as chaves que existem em dev e faltam em prod', () => {
  const dev = { DB_URL: 'x', API_KEY: 'y', PORT: '3000' };
  const prod = { DB_URL: 'x' };
  assert.deepEqual(faltantesNoAmbiente(dev, prod, ['DB_URL', 'API_KEY', 'PORT', 'DEBUG']), ['API_KEY', 'PORT']);
});

test('faltantesNoAmbiente devolve lista vazia quando a paridade está completa', () => {
  const dev = { DB_URL: 'x', API_KEY: 'y' };
  const prod = { DB_URL: 'x', API_KEY: 'y' };
  assert.deepEqual(faltantesNoAmbiente(dev, prod, ['DB_URL', 'API_KEY']), []);
});

test('versaoDoRollback devolve a versão saudável mais recente', () => {
  const historico = [
    { versao: 'v1', saudavel: false },
    { versao: 'v2', saudavel: true },
    { versao: 'v3', saudavel: false }
  ];
  assert.equal(versaoDoRollback(historico), 'v2');
});

test('versaoDoRollback devolve null quando nenhuma versão é saudável', () => {
  const historico = [
    { versao: 'v1', saudavel: false },
    { versao: 'v2', saudavel: false }
  ];
  assert.equal(versaoDoRollback(historico), null);
  assert.equal(versaoDoRollback([]), null);
});

solutionCode:
export function faltantesNoAmbiente(dev, prod, chaves) {
  if (!Array.isArray(chaves)) return [];
  return chaves.filter(
    (chave) => dev && dev[chave] !== undefined && prod && prod[chave] === undefined,
  );
}

export function versaoDoRollback(historico) {
  if (!Array.isArray(historico)) return null;
  let rollback = null;
  for (const item of historico) {
    if (item && item.saudavel === true) rollback = item.versao; // o último saudável vence
  }
  return rollback;
}
